 "content": "def transform(grid):
    # Fill the interiors of outlined rectangular frames. The common fill color
    # is 7; the frame whose color is 3 is filled with 2 (as demonstrated).
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 8 or (r, c) in seen:
                continue
            # identify connected monochromatic components
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            # Fill only rectangular frames: the component covers the full perimeter.
            perimeter = set()
            for x in range(c0,c1+1): perimeter.add((r0,x)); perimeter.add((r1,x))
            for y in range(r0,r1+1): perimeter.add((y,c0)); perimeter.add((y,c1))
            if len(comp) == len(perimeter) and set(comp) == perimeter and r1-r0 >= 2 and c1-c0 >= 2:
                fill = 2 if color == 3 else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if grid[y][x] == 8:
                            out[y][x] = fill
    return out

# Keep the compact demonstration contract available for local checks.
def _demo_transform(grid):
    return transform(grid)
